		continue
	for e in d.get("modifier_ledger", []):
		if typeof(e) == TYPE_DICTIONARY and str(e.get("source", "")) == "Strafing Run":
			seen.append(str(e.get("effect", "")))
print("[wp-o6] Strafing Run ledger rows: ", seen)
return seen.size() > 0
